import React, { useState } from "react";
import MainPage from "./MainPage";
import CharacterPage from "./CharacterPage";
import EducationPage from "./EducationPage";

export type PageId = "home" | "friend" | "edu" | "char" | "game" | "record";
export type CharKey = "bromi" | "saekomi" | "ttorong";

export const CHAR_IMAGES: Record<string, string[]> = {
  bromi:   ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"],
  saekomi: ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"],
  ttorong: ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"],
};

export const EDU_IMAGES: string[] = [
  "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,",
  "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"
];

const PAGE_NAMES: Record<string, string> = {
  home: "🏠 홈", friend: "🥕 영양 친구", edu: "📖 영양 배움터",
  char: "🏆 나의 건강 캐릭터", game: "🎮 미니 게임", record: "📋 나의 영양 기록",
};

const CHAR_META: Record<CharKey, { name: string; av: string }> = {
  bromi:   { name: "브로미",  av: "🥦" },
  saekomi: { name: "새콤이",  av: "🍎" },
  ttorong: { name: "또롱이",  av: "💧" },
};

export default function App() {
  const [page, setPage] = useState<string>("home");
  const [charPts, setCharPts] = useState<Record<CharKey, number>>({
    bromi: 0, saekomi: 0, ttorong: 0,
  });
  const [curChar, setCurChar] = useState<CharKey>("bromi");

  const showPage = (p: string) => { setPage(p); window.scrollTo(0, 0); };
  const levelUp = () => {
    setCharPts(prev => ({ ...prev, [curChar]: Math.min(30, prev[curChar] + 1) }));
  };

  const curPts = charPts[curChar];
  const { name, av } = CHAR_META[curChar];

  const SidebarItem = ({ id, icon, label }: { id: PageId; icon: string; label: string }) => (
    <div
      onClick={() => showPage(id)}
      style={{
        display: "flex", alignItems: "center", gap: 10,
        padding: "11px 13px", borderRadius: 12, cursor: "pointer",
        fontWeight: 700, fontSize: "0.88rem",
        color: page === id ? "#1a7a3e" : "#5a7366",
        background: page === id ? "#e8f9f0" : "transparent",
        border: `2px solid ${page === id ? "#a8f0c6" : "transparent"}`,
        marginBottom: 2,
      }}
    >
      <span style={{ fontSize: "1.1rem", width: 22, textAlign: "center" as const }}>{icon}</span>
      {label}
    </div>
  );

  return (
    <div style={{ display: "flex", minHeight: "100vh", fontFamily: "'Noto Sans KR', sans-serif", background: "#f4fdf7" }}>
      {/* Sidebar */}
      <div style={{
        width: 220, minWidth: 220, background: "white",
        borderRight: "2px solid #e9ecef", display: "flex",
        flexDirection: "column" as const, position: "fixed" as const,
        top: 0, left: 0, bottom: 0, zIndex: 200,
        boxShadow: "2px 0 16px rgba(46,204,113,.07)",
      }}>
        <div onClick={() => showPage("home")} style={{ padding: "20px 16px 18px", display: "flex", alignItems: "center", gap: 10, borderBottom: "2px solid #e9ecef", cursor: "pointer" }}>
          <div style={{ width: 38, height: 38, borderRadius: "50%", background: "#1a7a3e", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "1.3rem" }}>🥦</div>
          <div style={{ fontWeight: 900, fontSize: "0.88rem", color: "#1a7a3e", lineHeight: 1.35 }}>내 손안의<br />영양 짝꿍</div>
        </div>
        <div style={{ flex: 1, padding: "14px 10px", overflowY: "auto" as const }}>
          <div style={{ fontSize: "0.7rem", fontWeight: 700, color: "#adb5bd", textTransform: "uppercase" as const, letterSpacing: "0.1em", padding: "8px 10px 4px" }}>메뉴</div>
          <SidebarItem id="home"   icon="🏠" label="홈" />
          <SidebarItem id="friend" icon="🥕" label="영양 친구" />
          <SidebarItem id="edu"    icon="📖" label="영양 배움터" />
          <SidebarItem id="char"   icon="🏆" label="나의 건강 캐릭터" />
          <SidebarItem id="game"   icon="🎮" label="미니 게임" />
          <SidebarItem id="record" icon="📋" label="나의 영양 기록" />
        </div>
        <div style={{ padding: "14px 10px", borderTop: "2px solid #e9ecef" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "11px 13px", borderRadius: 12, background: "#e8f9f0" }}>
            <div style={{ width: 34, height: 34, borderRadius: "50%", background: "#2ecc71", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "1.2rem" }}>{av}</div>
            <div>
              <div style={{ fontSize: "0.82rem", fontWeight: 800, color: "#1a7a3e" }}>{name}</div>
              <div style={{ fontSize: "0.72rem", color: "#5a7366" }}>⭐ {curPts} / 30 pts</div>
            </div>
          </div>
        </div>
      </div>

      {/* Main */}
      <div style={{ marginLeft: 220, flex: 1, display: "flex", flexDirection: "column" as const }}>
        {/* Topbar */}
        <div style={{
          background: "rgba(255,255,255,.95)", borderBottom: "2px solid #e9ecef",
          padding: "0 28px", height: 58,
          display: "flex", alignItems: "center", justifyContent: "space-between",
          position: "sticky" as const, top: 0, zIndex: 100,
        }}>
          <span style={{ fontWeight: 900, fontSize: "1rem", color: "#1a7a3e" }}>{PAGE_NAMES[page]}</span>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ background: "#f9ca24", color: "#7a5800", borderRadius: 50, padding: "5px 14px", fontSize: "0.8rem", fontWeight: 800 }}>
              ⭐ {curPts} / 30 pts
            </span>
            <button onClick={() => showPage("edu")} style={{ background: "#1a7a3e", color: "white", border: "none", borderRadius: 50, padding: "8px 18px", fontSize: "0.8rem", fontWeight: 800, cursor: "pointer" }}>
              📚 학습하기
            </button>
          </div>
        </div>

        {/* Content */}
        <div style={{ padding: 28, flex: 1 }}>
          {page === "home"   && <MainPage showPage={showPage} />}
          {page === "char"   && <CharacterPage charPts={charPts} curChar={curChar} setCurChar={setCurChar} levelUp={levelUp} />}
          {page === "edu"    && <EducationPage />}
          {(page === "friend" || page === "game" || page === "record") && (
            <div style={{ display: "flex", flexDirection: "column" as const, alignItems: "center", justifyContent: "center", minHeight: 300, color: "#adb5bd" }}>
              <div style={{ fontSize: "4rem", marginBottom: 16, opacity: 0.4 }}>
                {page === "friend" ? "🥕" : page === "game" ? "🎮" : "📋"}
              </div>
              <div style={{ fontWeight: 900, fontSize: "1.2rem", marginBottom: 6 }}>{PAGE_NAMES[page]}</div>
              <div style={{ fontSize: "0.85rem" }}>곧 업데이트 예정입니다!</div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
